      const admNumber = tempAdmissionNumber.toUpperCase().trim();
      setAdmissionNumber(admNumber);
      localStorage.setItem('studentAdmissionNumber', admNumber);
      await loadFeeStatement(null, admNumber);
      setShowAdmissionModal(false);
