                          const paymentsForFee = myPayments.filter(p => p.feeId === fee.id);
                          const totalPaidForFee = paymentsForFee.reduce((sum, p) => sum + parseFloat(p.amount || 0), 0);
                          const isPaid = totalPaidForFee >= parseFloat(fee.amount);
                          
