  // ==================== EXTRACT NUMERIC VALUE ====================
  const extractNumber = (value) => {
    if (!value) return null;
    if (typeof value === 'number') return value;
    
    const str = String(value);
    const match = str.match(/\d+/);
    if (match) {
      return parseInt(match[0]);
    }
    const num = parseInt(str);
    if (!isNaN(num)) {
      return num;
    }
    return null;
  };

