  // ===== 6. fetchUser =====
  const fetchUser = async () => {
    try {
      const res = await api.get('/auth/me');
      const userData = res.data.user;
      
      if (userData.roleId) {
        try {
          const roleRes = await api.get(`/roles/${userData.roleId}`);
          if (roleRes.data.role) {
            userData.roleObject = roleRes.data.role;
            userData.permissions = roleRes.data.role.permissions || [];
            localStorage.setItem('userPermissions', JSON.stringify(userData.permissions));
          }
        } catch (err) {
          console.error('Error fetching user role:', err);
        }
      }
      
      const savedPermissions = localStorage.getItem('userPermissions');
      if (savedPermissions) {
        try {
          const perms = JSON.parse(savedPermissions);
          if (perms.length > 0 && !userData.permissions) {
            userData.permissions = perms;
          }
        } catch {
          // Ignore parse errors
        }
      }
      
      setUser(userData);
    } catch (err) {
      console.error('Fetch user error:', err);
      if (err.response?.status === 401) handleLogout();
    }
  };

  // ===== 7. fetchSchoolData, fetchAllData, fetchData =====
  const fetchSchoolData = async (schoolId) => {
    if (!schoolId) return;
    try {
      const [classesRes, studentsRes, subjectsRes, examsRes, feesRes, staffRes] = await Promise.allSettled([
        api.get(`/classes?schoolId=${schoolId}`), 
        api.get(`/students?schoolId=${schoolId}`), 
        api.get(`/subjects?schoolId=${schoolId}`),
        api.get(`/exams?schoolId=${schoolId}`), 
        api.get(`/fees?schoolId=${schoolId}`), 
        api.get(`/staff?schoolId=${schoolId}`)
      ]);

      if (classesRes.status === 'fulfilled' && classesRes.value?.data?.classes) setClasses(classesRes.value.data.classes); else setClasses([]);
      if (studentsRes.status === 'fulfilled' && studentsRes.value?.data?.students) setStudents(studentsRes.value.data.students); else setStudents([]);
      if (subjectsRes.status === 'fulfilled' && subjectsRes.value?.data?.subjects) setSubjects(subjectsRes.value.data.subjects); else setSubjects([]);
      if (examsRes.status === 'fulfilled' && examsRes.value?.data?.exams) setExams(examsRes.value.data.exams); else setExams([]);
      if (feesRes.status === 'fulfilled' && feesRes.value?.data?.fees) setFees(feesRes.value.data.fees); else setFees([]);
      if (staffRes.status === 'fulfilled' && staffRes.value?.data?.staff) setStaff(staffRes.value.data.staff); else setStaff([]);
    } catch (err) {
      console.error('Error fetching school data:', err);
    }
  };

